var decoderVersion = null;
if (msg.attributes != null) {
    var attrs = msg.attributes;
    if (attrs.deviceEUI != null) {
        dev = attrs.deviceEUI;
        // make sure it's got 4 symbols.
        if (dev.length() >= 4) {

            if (dev.substring(0, 4) == "AC1F") {
                // RAK radio chip
                decoderVersion = "Gen2";
            } else if (dev.substring(0, 4) ==
                // RN "Microchip" radio chip
                "0004") {
                decoderVersion = "Gen1";
            }
        }
    }
}

if (decoderVersion != null) {
    if (msg.attributes != null) {
        msg.attributes.decoderVersion = decoderVersion;
    } else {
        msg.attributes = {
            decoderVersion: decoderVersion
        };
    }
}

return {
    msg: msg,
    metadata: metadata,
    msgType: msgType
};

